import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { collection, getDocs, query, orderBy } from 'firebase/firestore';
import { db } from '../../firebase';
import { computeVendorStats } from '../../services/vendorService';
import { FiTrendingUp, FiUsers, FiBarChart2, FiDollarSign, FiRefreshCw, FiStar } from 'react-icons/fi';

export default function VendorPerformanceOverview() {
  const [vendors, setVendors] = useState([]);
  const [stats, setStats] = useState({});
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  const fetchData = async (isRefresh = false) => {
    try {
      if (isRefresh) setRefreshing(true); else setLoading(true);
      const vendorsSnap = await getDocs(query(collection(db, 'vendors'), orderBy('createdAt', 'desc')));
      const list = vendorsSnap.docs.map(d => ({ id: d.id, ...d.data() }));
      setVendors(list);
      const computed = await computeVendorStats(list);
      setStats(computed);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const totals = (() => {
    const sVals = Object.values(stats);
    return {
      totalVendors: vendors.length,
      totalPOs: sVals.reduce((a, v) => a + (v.totalPOs || 0), 0),
      totalJobs: sVals.reduce((a, v) => a + (v.totalJobs || 0), 0),
      totalSpend: sVals.reduce((a, v) => a + (v.totalSpend || 0), 0),
    };
  })();

  const topBySpend = [...vendors]
    .sort((a, b) => (stats[b.id]?.totalSpend || 0) - (stats[a.id]?.totalSpend || 0))
    .slice(0, 5);

  const topByRating = [...vendors]
    .sort((a, b) => (stats[b.id]?.computedRating || 0) - (stats[a.id]?.computedRating || 0))
    .slice(0, 5);

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-indigo-500"></div>
      </div>
    );
  }

  return (
    <div className="p-4 lg:p-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center">
              <FiTrendingUp className="text-white" size={20} />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Vendor Performance</h1>
              <p className="text-gray-600">Overview of vendor performance and quick access to detailed views</p>
            </div>
          </div>
          <button
            onClick={() => fetchData(true)}
            disabled={refreshing}
            className="flex items-center px-3 py-2 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 disabled:opacity-50"
          >
            <FiRefreshCw className={`mr-2 ${refreshing ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <SummaryCard icon={<FiUsers className="text-indigo-600" />} title="Total Vendors" value={totals.totalVendors} />
          <SummaryCard icon={<FiBarChart2 className="text-blue-600" />} title="Total POs" value={totals.totalPOs} />
          <SummaryCard icon={<FiBarChart2 className="text-emerald-600" />} title="Total Jobs" value={totals.totalJobs} />
          <SummaryCard icon={<FiDollarSign className="text-purple-600" />} title="Total Spend" value={`₹${totals.totalSpend.toLocaleString()}`} />
        </div>

        {/* Top Vendors by Spend */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200">
          <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
            <h2 className="text-lg font-semibold text-gray-900">Top Vendors by Spend</h2>
            <span className="text-sm text-gray-500">Last period</span>
          </div>
          <div className="divide-y divide-gray-100">
            {topBySpend.length === 0 ? (
              <div className="p-6 text-gray-500">No data available</div>
            ) : (
              topBySpend.map((v) => (
                <div key={v.id} className="px-6 py-4 flex items-center justify-between">
                  <div>
                    <div className="font-medium text-gray-900">{v.name}</div>
                    <div className="text-sm text-gray-500">{v.category || '—'}</div>
                  </div>
                  <div className="text-right">
                    <div className="font-semibold text-green-600">₹{(stats[v.id]?.totalSpend || 0).toLocaleString()}</div>
                    <div className="text-xs text-gray-500">POs: {stats[v.id]?.totalPOs || 0}</div>
                  </div>
                  <Link to={`/admin/vendor-performance/${v.id}`} className="ml-6 px-3 py-1.5 text-sm bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">
                    View Performance
                  </Link>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Top Vendors by Rating */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200">
          <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
            <h2 className="text-lg font-semibold text-gray-900">Top Vendors by Rating</h2>
          </div>
          <div className="divide-y divide-gray-100">
            {topByRating.length === 0 ? (
              <div className="p-6 text-gray-500">No ratings available</div>
            ) : (
              topByRating.map((v) => (
                <div key={v.id} className="px-6 py-4 flex items-center justify-between">
                  <div className="flex items-center">
                    <div className="font-medium text-gray-900 mr-3">{v.name}</div>
                    <div className="flex items-center text-yellow-500">
                      <FiStar className="mr-1" />
                      <span className="font-semibold">{(stats[v.id]?.computedRating || 0).toFixed(1)}</span>
                    </div>
                  </div>
                  <Link to={`/admin/vendor-performance/${v.id}`} className="ml-6 px-3 py-1.5 text-sm bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">
                    View Performance
                  </Link>
                </div>
              ))
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

function SummaryCard({ icon, title, value }) {
  return (
    <div className="rounded-lg border border-gray-200 bg-white p-6">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm text-gray-600">{title}</p>
          <p className="text-2xl font-bold text-gray-900 mt-1">{value}</p>
        </div>
        <div className="p-3 bg-gray-50 rounded-full">
          {icon}
        </div>
      </div>
    </div>
  );
}
